class BytesIOCopy:
    """Copies written bytes to another stream, while itself acting like an
    in-memory ``io.BytesIO`` for as long as possible.

    It is backed by a :class:`tempfile.SpooledTemporaryFile`, which only
    spills to a real, on-disk file when a real file descriptor is actually
    requested via ``fileno()``. This lets the stream be used as
    ``stdout``/``stderr`` for :func:`subprocess.run` and similar APIs that
    require a ``fileno()``, without paying the cost (or leaving unclosed
    file handles behind) when that is never needed.

    .. versionadded:: 8.2

    .. versionchanged:: 8.2.1
        Backed by ``tempfile.SpooledTemporaryFile`` instead of
        ``io.BytesIO`` so that ``fileno()`` works, fixing use with
        :mod:`subprocess`.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file = tempfile.SpooledTemporaryFile()
        self.copy_to = copy_to

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        try:
            return self._file.read()
        finally:
            self._file.seek(pos)

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

